import{_ as t,o as a,c as o,aN as l}from"./chunks/framework.D31DlcCL.js";const c=JSON.parse('{"title":"唐代诗人研究参考资料","description":"","frontmatter":{},"headers":[],"relativePath":"posts/tang-poets-reference.md","filePath":"posts/tang-poets-reference.md","lastUpdated":null}'),n={name:"posts/tang-poets-reference.md"};function i(s,r,e,g,h,d){return a(),o("div",null,[...r[0]||(r[0]=[l('<h1 id="唐代诗人研究参考资料" tabindex="-1">唐代诗人研究参考资料 <a class="header-anchor" href="#唐代诗人研究参考资料" aria-label="Permalink to &quot;唐代诗人研究参考资料&quot;">​</a></h1><h2 id="关键史料出处索引" tabindex="-1">关键史料出处索引 <a class="header-anchor" href="#关键史料出处索引" aria-label="Permalink to &quot;关键史料出处索引&quot;">​</a></h2><h3 id="王维研究史料" tabindex="-1">王维研究史料 <a class="header-anchor" href="#王维研究史料" aria-label="Permalink to &quot;王维研究史料&quot;">​</a></h3><ol><li><strong>《旧唐书·王维传》</strong> - 正史记载王维生平</li><li><strong>《新唐书·王维传》</strong> - 补充正史记载</li><li><strong>《唐才子传》</strong> - 唐代文人传记资料</li><li><strong>《唐诗纪事》</strong> - 唐代诗人事迹记载</li><li><strong>《王右丞集》</strong> - 王维作品集</li><li><strong>《宣和画谱》</strong> - 记载王维绘画成就</li><li><strong>《苏轼文集》</strong> - 苏轼对王维的评价</li><li><strong>《佛祖统纪》</strong> - 佛教史料，记录王维与佛教的关系</li></ol><h3 id="杜甫研究史料" tabindex="-1">杜甫研究史料 <a class="header-anchor" href="#杜甫研究史料" aria-label="Permalink to &quot;杜甫研究史料&quot;">​</a></h3><ol><li><strong>《旧唐书·杜甫传》</strong> - 正史记载杜甫生平</li><li><strong>《新唐书·杜甫传》</strong> - 补充正史记载</li><li><strong>《唐才子传》</strong> - 唐代文人传记资料</li><li><strong>《杜甫年谱》</strong> - 杜甫生平详细年表</li><li><strong>《杜工部集》</strong> - 杜甫作品集</li><li><strong>《杜诗镜铨》</strong> - 杜甫诗歌注解</li><li><strong>《读杜心解》</strong> - 杜甫诗歌解读</li><li><strong>《钱注杜诗》</strong> - 清代钱谦益注杜诗</li><li><strong>《仇注杜诗》</strong> - 清代仇兆鳌注杜诗</li><li><strong>《杨伦杜诗镜铨》</strong> - 清代杨伦注杜诗</li></ol><h2 id="唐代重要历史事件年表" tabindex="-1">唐代重要历史事件年表 <a class="header-anchor" href="#唐代重要历史事件年表" aria-label="Permalink to &quot;唐代重要历史事件年表&quot;">​</a></h2><h3 id="王维相关历史事件" tabindex="-1">王维相关历史事件 <a class="header-anchor" href="#王维相关历史事件" aria-label="Permalink to &quot;王维相关历史事件&quot;">​</a></h3><ul><li><strong>701年</strong> - 王维出生于太原王氏</li><li><strong>721年</strong> - 王维中进士第，开始仕宦生涯</li><li><strong>736年</strong> - 王维在长安任职，创作辋川别业</li><li><strong>755年</strong> - 安史之乱爆发，王维被迫接受伪职</li><li><strong>761年</strong> - 王维逝世</li></ul><h3 id="杜甫相关历史事件" tabindex="-1">杜甫相关历史事件 <a class="header-anchor" href="#杜甫相关历史事件" aria-label="Permalink to &quot;杜甫相关历史事件&quot;">​</a></h3><ul><li><strong>712年</strong> - 杜甫出生于巩县</li><li><strong>731年</strong> - 杜甫开始壮游生涯</li><li><strong>746年</strong> - 杜甫来到长安，开始&quot;长安十年&quot;</li><li><strong>755年</strong> - 安史之乱爆发，杜甫开始逃难生涯</li><li><strong>757年</strong> - 杜甫被任命为左拾遗</li><li><strong>759年</strong> - 杜甫来到成都，修建草堂</li><li><strong>762年</strong> - 严武去世，杜甫再次漂泊</li><li><strong>770年</strong> - 杜甫逝世</li></ul><h2 id="王维重要诗歌原文及白话译文" tabindex="-1">王维重要诗歌原文及白话译文 <a class="header-anchor" href="#王维重要诗歌原文及白话译文" aria-label="Permalink to &quot;王维重要诗歌原文及白话译文&quot;">​</a></h2><h3 id="_1-《山居秋暝》" tabindex="-1">1. 《山居秋暝》 <a class="header-anchor" href="#_1-《山居秋暝》" aria-label="Permalink to &quot;1. 《山居秋暝》&quot;">​</a></h3><p><strong>原文：</strong> 空山新雨后，天气晚来秋。 明月松间照，清泉石上流。 竹喧归浣女，莲动下渔舟。 随意春芳歇，王孙自可留。</p><p><strong>白话译文：</strong> 空旷的山林刚刚下过新雨，天气转凉已是晚秋。 明月的光辉透过松林洒下，清澈的泉水在石头上流淌。 竹林中传来洗衣女子归来的喧哗，莲叶摇曳中渔舟慢慢下行。 任凭春天的花草凋零，王孙贵族也可以在这里长久居住。</p><h3 id="_2-《鸟鸣涧》" tabindex="-1">2. 《鸟鸣涧》 <a class="header-anchor" href="#_2-《鸟鸣涧》" aria-label="Permalink to &quot;2. 《鸟鸣涧》&quot;">​</a></h3><p><strong>原文：</strong> 人闲桂花落，夜静春山空。 月出惊山鸟，时鸣春涧中。</p><p><strong>白话译文：</strong> 人闲适地坐着，桂花悄然飘落，夜晚寂静的山中显得格外空旷。 月亮升起惊动了山中的鸟儿，不时在春天的山涧中鸣叫。</p><h3 id="_3-《竹里馆》" tabindex="-1">3. 《竹里馆》 <a class="header-anchor" href="#_3-《竹里馆》" aria-label="Permalink to &quot;3. 《竹里馆》&quot;">​</a></h3><p><strong>原文：</strong> 独坐幽篁里，弹琴复长啸。 深林人不知，明月来相照。</p><p><strong>白话译文：</strong> 独自坐在幽深的竹林中，弹琴后又放声长啸。 深林中没有人知道，只有明月前来相照。</p><h3 id="_4-《相思》" tabindex="-1">4. 《相思》 <a class="header-anchor" href="#_4-《相思》" aria-label="Permalink to &quot;4. 《相思》&quot;">​</a></h3><p><strong>原文：</strong> 红豆生南国，春来发几枝。 愿君多采撷，此物最相思。</p><p><strong>白话译文：</strong> 红豆生长在南国，春天来了发出新枝。 希望您多多采摘，这个东西最能引起相思之情。</p><h3 id="_5-《少年行》" tabindex="-1">5. 《少年行》 <a class="header-anchor" href="#_5-《少年行》" aria-label="Permalink to &quot;5. 《少年行》&quot;">​</a></h3><p><strong>原文：</strong> 新丰美酒斗十千，咸阳游侠多少年。 相逢意气为君饮，系马高楼垂柳边。</p><p><strong>白话译文：</strong> 新丰的美酒一斗价值十千钱，咸阳的游侠都是年轻人。 相逢时意气相投为您而饮，把马系在高楼旁的垂柳树下。</p><h3 id="_6-《凝碧池》" tabindex="-1">6. 《凝碧池》 <a class="header-anchor" href="#_6-《凝碧池》" aria-label="Permalink to &quot;6. 《凝碧池》&quot;">​</a></h3><p><strong>原文：</strong> 万户伤心生野烟，百官何日更朝天？ 秋槐叶落空宫里，凝碧池头奏管弦。</p><p><strong>白话译文：</strong> 万户人家因战乱而生出悲伤的烟火，百官们什么时候才能再朝见天子？ 秋天的槐叶飘落在空旷的宫殿里，凝碧池头还在演奏着管弦乐。</p><h2 id="杜甫重要诗歌原文及白话译文" tabindex="-1">杜甫重要诗歌原文及白话译文 <a class="header-anchor" href="#杜甫重要诗歌原文及白话译文" aria-label="Permalink to &quot;杜甫重要诗歌原文及白话译文&quot;">​</a></h2><h3 id="_1-《望岳》" tabindex="-1">1. 《望岳》 <a class="header-anchor" href="#_1-《望岳》" aria-label="Permalink to &quot;1. 《望岳》&quot;">​</a></h3><p><strong>原文：</strong> 岱宗夫如何？齐鲁青未了。 造化钟神秀，阴阳割昏晓。 荡胸生曾云，决眦入归鸟。 会当凌绝顶，一览众山小。</p><p><strong>白话译文：</strong> 泰山是什么样子？齐鲁大地上的青色连绵不绝。 大自然将神奇秀美都集中在这里，山的南北分割了昏晓。 胸怀激荡生出层层云霞，极目追踪归巢的鸟儿。 一定要登上泰山的最高峰，俯瞰群山都觉得渺小。</p><h3 id="_2-《春望》" tabindex="-1">2. 《春望》 <a class="header-anchor" href="#_2-《春望》" aria-label="Permalink to &quot;2. 《春望》&quot;">​</a></h3><p><strong>原文：</strong> 国破山河在，城春草木深。 感时花溅泪，恨别鸟惊心。 烽火连三月，家书抵万金。 白头搔更短，浑欲不胜簪。</p><p><strong>白话译文：</strong> 国家破碎但山河依然存在，春天的城里草木丛生。 感伤时事看到花都落泪，怨恨离别听到鸟都惊心。 战火连绵不断已经三个月家信珍贵得抵万金。 白发越搔越稀疏，简直插不上发簪了。</p><h3 id="_3-《登高》" tabindex="-1">3. 《登高》 <a class="header-anchor" href="#_3-《登高》" aria-label="Permalink to &quot;3. 《登高》&quot;">​</a></h3><p><strong>原文：</strong> 风急天高猿啸哀，渚清沙白鸟飞回。 无边落木萧萧下，不尽长江滚滚来。 万里悲秋常作客，百年多病独登台。 艰难苦恨繁霜鬓，潦倒新停浊酒杯。</p><p><strong>白话译文：</strong> 风急天高猿猴啼叫悲哀，小洲清澈沙滩洁白鸟儿飞回。 无边无际的落叶萧萧飘下，不尽的长江滚滚涌来。 万里悲秋常常作客他乡，百年多病独自登上高台。 艰难困苦使白发增多，潦倒新近停了浊酒杯。</p><h3 id="_4-《茅屋为秋风所破歌》" tabindex="-1">4. 《茅屋为秋风所破歌》 <a class="header-anchor" href="#_4-《茅屋为秋风所破歌》" aria-label="Permalink to &quot;4. 《茅屋为秋风所破歌》&quot;">​</a></h3><p><strong>原文：</strong> 八月秋高风怒号，卷我屋上三重茅。 茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。 南村群童欺我老无力，忍能对面为盗贼。 公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。 俄顷风定云墨色，秋天漠漠向昏黑。 布衾多年冷似铁，娇儿恶卧踏里裂。 床头屋漏无干处，雨脚如麻未断绝。 自经丧乱少睡眠，长夜沾湿何由彻！ 安得广厦千万间，大庇天下寒士俱欢颜！ 风雨不动安如山。呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！</p><p><strong>白话译文：</strong> 八月秋高风怒号，卷走我屋顶上的三层茅草。 茅草飞过江洒在江边，高的挂在树梢，低的飘落在池塘里。 南村的孩子们欺负我年老无力，竟当面做盗贼。 公然抱着茅草跑进竹林，我喊得口干舌燥也无法阻止，回来拄着拐杖叹息。 一会儿风停云黑，秋天昏暗。 布盖多年冷得像铁，孩子睡觉不好踢破了里面。 床头的房子漏水没有干的地方，雨点像麻一样没断过。 自从战乱很少睡眠，长夜潮湿怎么才能天亮！ 怎么能得到千万间大房子，天下贫寒的读书人都欢颜！ 风雨不动安稳如山。唉！什么时候眼前突然出现这样的房子，我的房子破了自己受冻死也甘心！</p><h3 id="_5-《绝句四首》其三" tabindex="-1">5. 《绝句四首》其三 <a class="header-anchor" href="#_5-《绝句四首》其三" aria-label="Permalink to &quot;5. 《绝句四首》其三&quot;">​</a></h3><p><strong>原文：</strong> 两个黄鹂鸣翠柳，一行白鹭上青天。 窗含西岭千秋雪，门泊东吴万里船。</p><p><strong>白话译文：</strong> 两只黄鹂在翠绿的柳树上鸣叫，一行白鹭飞向青天。 窗户含着西岭千秋雪，门前停泊着东吴万里船。</p><h3 id="_6-《自京赴奉先县咏怀五百字》" tabindex="-1">6. 《自京赴奉先县咏怀五百字》 <a class="header-anchor" href="#_6-《自京赴奉先县咏怀五百字》" aria-label="Permalink to &quot;6. 《自京赴奉先县咏怀五百字》&quot;">​</a></h3><p><strong>原文：</strong> 杜陵有布衣，老大意转拙。 许身一何愚，窃比稷与契。 居然成濩落，白首甘契阔。 盖棺事则已，此志常觊豁。 穷年忧黎元，叹息肠内热。 取笑同学翁，浩歌弥激烈。 非无江海志，潇洒送日月。 生逢尧舜君，不忍便永诀。 当今廊庙具，构厦岂云缺？ 葵藿倾太阳，物性固莫夺。 顾惟群蚁辈，但自求其穴。 胡为慕大鲸，辄拟偃溟渤？ 以兹误生理，独耻事干谒。 兀兀遂至今，忍为尘埃没。 终愧巢与由，未能易其节。 沉饮聊自遣，放歌破愁绝。</p><p><strong>白话译文：</strong> 杜陵有个平民，年纪大了更加笨拙。 许身报国多么愚蠢，私下里自比稷和契。 竟然这样无所成就，到老甘愿受苦。 盖棺才算结束，这个志向常常希望能够实现。 一年到头忧愁百姓，叹息内心发热。 被同辈嘲笑，放声歌唱更加激烈。 不是没有隐居的志向，也能潇洒地度过时光。 生逢尧舜那样的君主，不忍心就此告别。 当今朝廷都有栋梁，建造房屋难道还缺吗？ 葵藿向着太阳，物的本性不能改变。 只是看着那些群蚁般的人，只求自己的洞穴。 为什么羡慕大鲸鱼，想要在海洋里遨游？ 因为这个耽误了生计，独独耻于干谒奔走。 平庸到今天，忍心被尘埃淹没。 最终愧对巢父和许由，不能改变自己的节操。 沉醉酒中聊且自我排遣，放声歌唱破除愁苦。</p><h2 id="唐代官职术语表" tabindex="-1">唐代官职术语表 <a class="header-anchor" href="#唐代官职术语表" aria-label="Permalink to &quot;唐代官职术语表&quot;">​</a></h2><h3 id="中央官职" tabindex="-1">中央官职 <a class="header-anchor" href="#中央官职" aria-label="Permalink to &quot;中央官职&quot;">​</a></h3><h4 id="三省系统" tabindex="-1">三省系统 <a class="header-anchor" href="#三省系统" aria-label="Permalink to &quot;三省系统&quot;">​</a></h4><ul><li><strong>尚书省</strong>：最高行政机关，下设六部</li><li><strong>中书省</strong>：负责起草诏令的机关</li><li><strong>门下省</strong>：负责审核诏令的机关</li><li><strong>三省</strong>：中书、门下、尚书三省合称</li></ul><h4 id="各部官员" tabindex="-1">各部官员 <a class="header-anchor" href="#各部官员" aria-label="Permalink to &quot;各部官员&quot;">​</a></h4><ul><li><strong>尚书</strong>：各部的最高长官</li><li><strong>侍郎</strong>：各部的副长官</li><li><strong>郎中</strong>：各司的长官</li><li><strong>员外郎</strong>：各司的副长官</li><li><strong>司功参军</strong>：负责功绩考核的官员</li><li><strong>左司郎中</strong>：尚书省官员，负责行政事务</li><li><strong>右司郎中</strong>：尚书省官员，负责行政事务</li></ul><h4 id="谏官系统" tabindex="-1">谏官系统 <a class="header-anchor" href="#谏官系统" aria-label="Permalink to &quot;谏官系统&quot;">​</a></h4><ul><li><strong>左拾遗</strong>：谏官，负责向皇帝提建议</li><li><strong>右补阙</strong>：谏官，负责向皇帝提建议</li><li><strong>给事中</strong>：门下省官员，负责审核诏令</li></ul><h4 id="文学侍从" tabindex="-1">文学侍从 <a class="header-anchor" href="#文学侍从" aria-label="Permalink to &quot;文学侍从&quot;">​</a></h4><ul><li><strong>翰林学士</strong>：皇帝的文学侍从</li><li><strong>侍读</strong>：为皇帝讲学的官员</li><li><strong>侍讲</strong>：为皇帝讲解经书的官员</li><li><strong>集贤殿学士</strong>：负责整理典籍的官员</li></ul><h3 id="地方官职" tabindex="-1">地方官职 <a class="header-anchor" href="#地方官职" aria-label="Permalink to &quot;地方官职&quot;">​</a></h3><h4 id="州级官员" tabindex="-1">州级官员 <a class="header-anchor" href="#州级官员" aria-label="Permalink to &quot;州级官员&quot;">​</a></h4><ul><li><strong>刺史</strong>：州的长官</li><li><strong>司马</strong>：州的副长官</li><li><strong>参军</strong>：州的属官</li><li><strong>主簿</strong>：负责文书工作的官员</li><li><strong>录事参军</strong>：负责文书和行政工作的官员</li><li><strong>司功参军</strong>：负责功绩考核的官员</li></ul><h4 id="郡县级官员" tabindex="-1">郡县级官员 <a class="header-anchor" href="#郡县级官员" aria-label="Permalink to &quot;郡县级官员&quot;">​</a></h4><ul><li><strong>太守</strong>：郡的长官</li><li><strong>县令</strong>：县的长官</li><li><strong>县尉</strong>：县的副长官，负责治安</li><li><strong>主簿</strong>：负责文书工作的官员</li></ul><h4 id="军事官员" tabindex="-1">军事官员 <a class="header-anchor" href="#军事官员" aria-label="Permalink to &quot;军事官员&quot;">​</a></h4><ul><li><strong>节度使</strong>：地区的军事长官</li><li><strong>观察使</strong>：观察地区的官员</li><li><strong>都护</strong>：边疆地区的军事长官</li><li><strong>镇将</strong>：军事要塞的指挥官</li></ul><h3 id="荣誉性官职" tabindex="-1">荣誉性官职 <a class="header-anchor" href="#荣誉性官职" aria-label="Permalink to &quot;荣誉性官职&quot;">​</a></h3><h4 id="临时官职" tabindex="-1">临时官职 <a class="header-anchor" href="#临时官职" aria-label="Permalink to &quot;临时官职&quot;">​</a></h4><ul><li><strong>检校</strong>：临时担任某官职的称号</li><li><strong>行</strong>：临时担任某官职的称号</li><li><strong>守</strong>：暂时担任某官职的称号</li><li><strong>摄</strong>：代理某官职的称号</li><li><strong>兼</strong>：兼任某官职的称号</li><li><strong>判</strong>：负责某项工作的官员</li><li><strong>知</strong>：主持某项工作的官员</li></ul><h4 id="特殊荣誉官职" tabindex="-1">特殊荣誉官职 <a class="header-anchor" href="#特殊荣誉官职" aria-label="Permalink to &quot;特殊荣誉官职&quot;">​</a></h4><ul><li><strong>工部员外郎</strong>：工部的副长官</li><li><strong>华州司功参军</strong>：华州负责功绩考核的官员</li><li><strong>剑南节度使</strong>：剑南地区的军事长官</li><li><strong>检校工部员外郎</strong>：临时担任工部员外郎的官员</li></ul><h3 id="监察官员" tabindex="-1">监察官员 <a class="header-anchor" href="#监察官员" aria-label="Permalink to &quot;监察官员&quot;">​</a></h3><h4 id="御察系统" tabindex="-1">御察系统 <a class="header-anchor" href="#御察系统" aria-label="Permalink to &quot;御察系统&quot;">​</a></h4><ul><li><strong>御史</strong>：负责监察的官员</li><li><strong>殿中侍御史</strong>：在朝堂上监察百官的官员</li><li><strong>监察御史</strong>：负责监察百官的官员</li><li><strong>监察里行</strong>：监察官员的属官</li></ul><h4 id="地方监察" tabindex="-1">地方监察 <a class="header-anchor" href="#地方监察" aria-label="Permalink to &quot;地方监察&quot;">​</a></h4><ul><li><strong>采访使</strong>：负责监察地方的官员</li><li><strong>观察使</strong>：观察地方的官员</li></ul><h3 id="其他重要官职" tabindex="-1">其他重要官职 <a class="header-anchor" href="#其他重要官职" aria-label="Permalink to &quot;其他重要官职&quot;">​</a></h3><h4 id="教育官员" tabindex="-1">教育官员 <a class="header-anchor" href="#教育官员" aria-label="Permalink to &quot;教育官员&quot;">​</a></h4><ul><li><strong>国子祭酒</strong>：国子监的最高长官</li><li><strong>国子司业</strong>：国子监的副长官</li><li><strong>博士</strong>：负责教学的官员</li><li><strong>助教</strong>：协助教学的官员</li></ul><h4 id="宗教官员" tabindex="-1">宗教官员 <a class="header-anchor" href="#宗教官员" aria-label="Permalink to &quot;宗教官员&quot;">​</a></h4><ul><li><strong>祠部郎中</strong>：负责祭祀的官员</li><li><strong>太常博士</strong>：负责礼仪祭祀的官员</li><li><strong>太常寺卿</strong>：负责祭祀礼仪的长官</li></ul><h4 id="外交官员" tabindex="-1">外交官员 <a class="header-anchor" href="#外交官员" aria-label="Permalink to &quot;外交官员&quot;">​</a></h4><ul><li><strong>鸿胪卿</strong>：负责外交的长官</li><li><strong>鸿胪少卿</strong>：负责外交的副长官</li><li><strong>典客</strong>：负责接待外宾的官员</li></ul><h4 id="宫廷官员" tabindex="-1">宫廷官员 <a class="header-anchor" href="#宫廷官员" aria-label="Permalink to &quot;宫廷官员&quot;">​</a></h4><ul><li><strong>殿中监</strong>：负责宫廷事务的官员</li><li><strong>尚食局</strong>：负责皇帝饮食的官员</li><li><strong>尚药局</strong>：负责皇帝医药的官员</li></ul><h2 id="唐代文化术语" tabindex="-1">唐代文化术语 <a class="header-anchor" href="#唐代文化术语" aria-label="Permalink to &quot;唐代文化术语&quot;">​</a></h2><h3 id="佛教术语" tabindex="-1">佛教术语 <a class="header-anchor" href="#佛教术语" aria-label="Permalink to &quot;佛教术语&quot;">​</a></h3><ul><li><strong>禅宗</strong>：中国佛教宗派，强调直指人心，见性成佛</li><li><strong>北宗禅</strong>：强调渐修的禅宗流派</li><li><strong>南宗禅</strong>：强调顿悟的禅宗流派</li><li><strong>维摩诘</strong>：佛教居士，王维名字的来源</li><li><strong>净土宗</strong>：强调往生西方净土的佛教宗派</li></ul><h3 id="文学术语" tabindex="-1">文学术语 <a class="header-anchor" href="#文学术语" aria-label="Permalink to &quot;文学术语&quot;">​</a></h3><ul><li><strong>诗佛</strong>：对王维的称呼，指其诗歌具有禅宗特色</li><li><strong>诗史</strong>：对杜甫的称呼，指其诗歌记录历史</li><li><strong>诗圣</strong>：对杜甫的尊称，指其诗歌成就达到圣人的境界</li><li><strong>律诗</strong>：唐代格律诗的一种，分为五言和七言</li><li><strong>绝句</strong>：唐代格律诗的一种，分为五言和七言</li><li><strong>古体诗</strong>：不拘格律的诗歌形式</li></ul><h3 id="历史术语" tabindex="-1">历史术语 <a class="header-anchor" href="#历史术语" aria-label="Permalink to &quot;历史术语&quot;">​</a></h3><ul><li><strong>安史之乱</strong>：755-763年的叛乱，是唐代由盛转衰的转折点</li><li><strong>开元盛世</strong>：唐玄宗开元年间（713-741年）的繁荣时期</li><li><strong>天宝盛世</strong>：唐玄宗天宝年间（742-756年）的繁荣时期</li><li><strong>藩镇割据</strong>：唐代后期地方节度使割据的局面</li><li><strong>牛李党争</strong>：唐代后期牛僧孺和李德裕之间的政治斗争</li></ul><h3 id="社会术语" tabindex="-1">社会术语 <a class="header-anchor" href="#社会术语" aria-label="Permalink to &quot;社会术语&quot;">​</a></h3><ul><li><strong>门第</strong>：家族的社会地位和等级</li><li><strong>科举</strong>：唐代选拔官员的制度</li><li><strong>进士</strong>：科举考试的最高功名</li><li><strong>明经</strong>：科举考试的科目之一</li><li><strong>明法</strong>：科举考试的科目之一</li></ul><hr><p><em>注：本参考资料为唐代诗人研究提供全面的历史背景、文本资料和术语解释，可作为深度研究的辅助材料。</em></p>',96)])])}const q=t(n,[["render",i]]);export{c as __pageData,q as default};
